from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    fill, divider = [v for v, _ in counts.most_common(2)]
    rows = [r for r in range(h) if grid[r].count(divider) > w // 2]
    cols = [c for c in range(w) if sum(grid[r][c] == divider for r in range(h)) > h // 2]
    out = []
    for r1, r2 in zip(rows, rows[1:]):
        row = []
        for c1, c2 in zip(cols, cols[1:]):
            a, b = grid[r1][c1], grid[r1][c2]
            c, d = grid[r2][c1], grid[r2][c2]
            row.append(a if a == b == c == d and a != divider else fill)
        out.append(row)
    # Trim only all-background outside margins.
    while out and all(v == fill for v in out[0]):
        out.pop(0)
    while out and all(v == fill for v in out[-1]):
        out.pop()
    while out and out[0] and all(row[0] == fill for row in out):
        for row in out:
            row.pop(0)
    while out and out[0] and all(row[-1] == fill for row in out):
        for row in out:
            row.pop()
    return out

